import{_ as l,o as i,c as t,a2 as r}from"./chunks/framework.GbRRgL9t.js";const c=JSON.parse('{"title":"用户指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1789902237000}'),e={name:"guide/usage.md"};function o(n,a,s,h,u,d){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="用户指南" tabindex="-1">用户指南 <a class="header-anchor" href="#用户指南" aria-label="Permalink to &quot;用户指南&quot;">​</a></h1><p>面向普通用户的 CircleChat 功能手册。</p><h2 id="注册与登录" tabindex="-1">注册与登录 <a class="header-anchor" href="#注册与登录" aria-label="Permalink to &quot;注册与登录&quot;">​</a></h2><ul><li>访问根路径 <code>/</code> 自动跳转登录页。</li><li>可注册（开放注册时）；注册后可能需等待管理员审核（pending 状态无法登录，通过后才能登录）。</li><li>登录失败连续 5 次会被限速 10 分钟。</li></ul><h2 id="界面组成" tabindex="-1">界面组成 <a class="header-anchor" href="#界面组成" aria-label="Permalink to &quot;界面组成&quot;">​</a></h2><ul><li><strong>左侧栏</strong>：会话列表（群组 / 私聊）、好友、群的入口、顶部铃铛（站内信箱）。</li><li><strong>主区</strong>：当前会话的消息流与输入框。</li><li>支持 <strong>zh / en / ja</strong> 三种界面语言（右上角切换）。</li></ul><h2 id="私聊" tabindex="-1">私聊 <a class="header-anchor" href="#私聊" aria-label="Permalink to &quot;私聊&quot;">​</a></h2><ul><li>通过搜索/加好友建立私聊；<strong>必须先互为好友</strong>才能发起私聊。</li><li>在线状态、正在输入提示（仅好友可见）。</li></ul><h2 id="群组" tabindex="-1">群组 <a class="header-anchor" href="#群组" aria-label="Permalink to &quot;群组&quot;">​</a></h2><ul><li>可创建群、搜索并加入群、申请入群（需审核的群）。</li><li>群主 / 管理员可：解散、重命名、设公告、移出成员、审核入群、转让群主、删除群文件。</li><li>群内多人实时聊天。</li></ul><h2 id="发消息" tabindex="-1">发消息 <a class="header-anchor" href="#发消息" aria-label="Permalink to &quot;发消息&quot;">​</a></h2><ul><li>文本消息支持 <strong>Markdown</strong> 渲染与<strong>代码高亮</strong>（highlight.js），支持<strong>数学公式</strong>（MathJax）。</li><li>可以<strong>引用回复</strong>某条消息。</li><li>支持发送：图片 / 音频 / 视频 / 文件，以及<strong>合并转发</strong>。</li></ul><h2 id="上传文件" tabindex="-1">上传文件 <a class="header-anchor" href="#上传文件" aria-label="Permalink to &quot;上传文件&quot;">​</a></h2><ul><li>单文件上限 100MB；大文件走<strong>分片断点续传</strong>（自动，无需手动操作）。</li><li>上传时界面会显示分段进度条与总百分比，文件面板出现时消息上移。</li><li>上传类型有白名单 + 图片魔数校验，非白名单会被拒绝。</li></ul><h2 id="表情回应" tabindex="-1">表情回应 <a class="header-anchor" href="#表情回应" aria-label="Permalink to &quot;表情回应&quot;">​</a></h2><p>对任意一条未撤回的消息，可添加 / 切换 / 取消 emoji 回应。</p><h2 id="撤回消息" tabindex="-1">撤回消息 <a class="header-anchor" href="#撤回消息" aria-label="Permalink to &quot;撤回消息&quot;">​</a></h2><ul><li>可撤回<strong>自己的</strong>消息。</li><li>管理员可撤回<strong>任意人</strong>的消息（前端会标记为管理员代删）。</li></ul><h2 id="消息操作" tabindex="-1">消息操作 <a class="header-anchor" href="#消息操作" aria-label="Permalink to &quot;消息操作&quot;">​</a></h2><p>消息上可打开上下文菜单（右键 / 长按），支持：</p><ul><li>引用回复</li><li>表情回应</li><li>撤回（若允许）</li><li><strong>举报</strong>（弹出输入框填写原因，进入管理员处理）</li><li>转发 / 合并转发</li><li>音频拖动进度、音视频下载</li></ul><h2 id="站点信箱" tabindex="-1">站点信箱 <a class="header-anchor" href="#站点信箱" aria-label="Permalink to &quot;站点信箱&quot;">​</a></h2><p>点击顶部<strong>铃铛</strong>打开信箱，含三个标签：</p><ul><li><strong>公告</strong>：系统级全局公告。</li><li><strong>通知</strong>：个人通知（如处罚结果）。</li><li><strong>我的处罚</strong>：我的历史处罚记录。</li></ul><h2 id="个人中心与账号安全" tabindex="-1">个人中心与账号安全 <a class="header-anchor" href="#个人中心与账号安全" aria-label="Permalink to &quot;个人中心与账号安全&quot;">​</a></h2><p>在个人中心可：</p><ul><li>修改昵称、签名、头像。</li><li>修改密码（需要旧密码）。</li><li>设置在线 / 隐身 / 离开状态。</li><li>开启 / 关闭<strong>两步验证（TOTP 二维码）</strong>。</li></ul><h3 id="安全提示" tabindex="-1">安全提示 <a class="header-anchor" href="#安全提示" aria-label="Permalink to &quot;安全提示&quot;">​</a></h3><ul><li>密码 SHA256 加盐存储，会话用 HttpOnly Cookie。</li><li>生产环境请尽快修改管理员默认密码（若你是管理员）。</li><li>被禁言 / 封禁后无法继续发消息，前端会收到处罚提示。</li></ul>',29)])])}const b=l(e,[["render",o]]);export{c as __pageData,b as default};
